/**
 * localdoc.org — DocxBuilder & MiniZip (In-Memory OpenXML .docx Generator)
 * Builds genuine Microsoft Word (.docx) OpenXML archives with rich formatting in pure client-side JavaScript.
 * 100% Client-Side RAM Execution. Zero External Server Dependencies.
 */

class DocxBuilder {
  static escapeXml(str) {
    if (!str && str !== 0) return '';
    return String(str)
      .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '') // remove invalid XML control chars
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }

  static createRunXml(run) {
    if (!run) return '';
    if (run.isTab) {
      return '<w:r><w:tab/></w:r>';
    }

    const text = this.escapeXml(run.text || '');
    if (!text && !run.isTab) return '';

    let rPr = '<w:rPr>';
    const font = this.escapeXml(run.fontFamily || 'Calibri');
    rPr += `<w:rFonts w:ascii="${font}" w:hAnsi="${font}" w:cs="${font}"/>`;

    if (run.bold) {
      rPr += '<w:b/><w:bCs/>';
    }
    if (run.italic) {
      rPr += '<w:i/><w:iCs/>';
    }
    if (run.underline) {
      rPr += '<w:u w:val="single"/>';
    }
    if (run.fontSize) {
      const halfPoints = Math.round(run.fontSize);
      rPr += `<w:sz w:val="${halfPoints}"/><w:szCs w:val="${halfPoints}"/>`;
    }
    if (run.color) {
      const hex = String(run.color).replace('#', '');
      rPr += `<w:color w:val="${hex}"/>`;
    }
    rPr += '</w:rPr>';

    return `<w:r>${rPr}<w:t xml:space="preserve">${text}</w:t></w:r>`;
  }

  static createParagraphXml(p) {
    if (!p) return '<w:p/>';

    // If it's a simple string, wrap in default paragraph
    if (typeof p === 'string') {
      const clean = this.escapeXml(p);
      return `<w:p><w:pPr><w:spacing w:before="60" w:after="60" w:line="240" w:lineRule="auto"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Calibri" w:hAnsi="Calibri"/><w:sz w:val="22"/></w:rPr><w:t xml:space="preserve">${clean}</w:t></w:r></w:p>`;
    }

    // Handle divider rule
    if (p.type === 'divider') {
      return `<w:p><w:pPr><w:pBdr><w:bottom w:val="single" w:sz="8" w:space="1" w:color="CBD5E1"/></w:pBdr><w:spacing w:before="120" w:after="120"/></w:pPr></w:p>`;
    }

    // Handle Table
    if (p.type === 'table' && Array.isArray(p.rows)) {
      return this.createTableXml(p);
    }

    // Build paragraph properties <w:pPr>
    let pPr = '<w:pPr>';
    
    // Alignment
    if (p.align && ['center', 'right', 'both', 'left'].includes(p.align)) {
      pPr += `<w:jc w:val="${p.align}"/>`;
    }

    // Spacing
    const before = p.spacingBefore !== undefined ? p.spacingBefore : (p.type === 'heading' ? 200 : (p.isBullet ? 40 : 60));
    const after = p.spacingAfter !== undefined ? p.spacingAfter : (p.type === 'heading' ? 80 : (p.isBullet ? 40 : 60));
    pPr += `<w:spacing w:before="${before}" w:after="${after}" w:line="240" w:lineRule="auto"/>`;

    // Bottom border (for Section Headings e.g. "EXPERIENCE", "EDUCATION")
    if (p.hasBottomBorder || (p.type === 'heading' && p.headingLevel <= 2)) {
      const bColor = p.borderColor || '94A3B8';
      pPr += `<w:pBdr><w:bottom w:val="single" w:sz="8" w:space="3" w:color="${bColor}"/></w:pBdr>`;
    }

    // Bullet indentation
    if (p.isBullet || p.type === 'bullet') {
      pPr += '<w:ind w:left="540" w:hanging="280"/>';
    }

    // Right-aligned Tab stop (e.g. Job Title on left, Dates on right)
    if (p.hasRightTab) {
      const tabPos = p.tabPos || 9072; // default right margin for A4 with 1 inch margin
      pPr += `<w:tabs><w:tab w:val="right" w:pos="${tabPos}"/></w:tabs>`;
    }

    pPr += '</w:pPr>';

    // Build Runs <w:r>
    let runsXml = '';

    // Bullet symbol run
    if (p.isBullet || p.type === 'bullet') {
      const bulletSymbol = p.bulletChar || '•';
      runsXml += `<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:b/><w:sz w:val="22"/><w:color w:val="334155"/></w:rPr><w:t xml:space="preserve">${this.escapeXml(bulletSymbol)} </w:t></w:r>`;
    }

    if (Array.isArray(p.runs)) {
      p.runs.forEach(run => {
        runsXml += this.createRunXml(run);
      });
    } else if (p.text) {
      runsXml += this.createRunXml({
        text: p.text,
        bold: p.bold || p.type === 'heading',
        italic: p.italic,
        fontSize: p.fontSize || (p.type === 'heading' ? (p.headingLevel === 1 ? 32 : 26) : 22),
        color: p.color || (p.type === 'heading' ? '0F172A' : '334155')
      });
    }

    return `<w:p>${pPr}${runsXml}</w:p>`;
  }

  static createTableXml(tableData) {
    const rows = tableData.rows || [];
    if (rows.length === 0) return '';

    let tableXml = '<w:tbl><w:tblPr><w:tblW w:w="9072" w:type="dxa"/><w:tblBorders><w:top w:val="single" w:sz="4" w:space="0" w:color="CBD5E1"/><w:left w:val="single" w:sz="4" w:space="0" w:color="CBD5E1"/><w:bottom w:val="single" w:sz="4" w:space="0" w:color="CBD5E1"/><w:right w:val="single" w:sz="4" w:space="0" w:color="CBD5E1"/><w:insideH w:val="single" w:sz="4" w:space="0" w:color="E2E8F0"/><w:insideV w:val="single" w:sz="4" w:space="0" w:color="E2E8F0"/></w:tblBorders><w:tblCellMar><w:top w:w="120" w:type="dxa"/><w:left w:w="160" w:type="dxa"/><w:bottom w:w="120" w:type="dxa"/><w:right w:w="160" w:type="dxa"/></w:tblCellMar></w:tblPr>';

    rows.forEach((row, rIdx) => {
      const isHeader = rIdx === 0 && tableData.hasHeader !== false;
      tableXml += '<w:tr>';
      if (isHeader) {
        tableXml += '<w:trPr><w:tblHeader/></w:trPr>';
      }

      const cells = Array.isArray(row) ? row : (row.cells || []);
      cells.forEach(cell => {
        const cellText = typeof cell === 'string' ? cell : (cell.text || '');
        const isBold = isHeader || (cell.bold === true);
        const bgHex = isHeader ? 'F1F5F9' : (cell.bgColor || 'FFFFFF');

        tableXml += `<w:tc><w:tcPr><w:shd w:val="clear" w:color="auto" w:fill="${bgHex}"/></w:tcPr><w:p><w:pPr><w:spacing w:before="40" w:after="40"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Calibri" w:hAnsi="Calibri"/>${isBold ? '<w:b/>' : ''}<w:sz w:val="20"/><w:color w:val="${isBold ? '0F172A' : '334155'}"/></w:rPr><w:t xml:space="preserve">${this.escapeXml(cellText)}</w:t></w:r></w:p></w:tc>`;
      });

      tableXml += '</w:tr>';
    });

    tableXml += '</w:tbl>';
    return tableXml;
  }

  static createDocxFromContent(paragraphs, options = {}) {
    const docTitle = this.escapeXml(options.title || 'Converted Document');
    const author = this.escapeXml(options.author || 'LocalDoc.org (Zero-Upload)');

    let bodyContentXml = '';
    paragraphs.forEach(p => {
      bodyContentXml += this.createParagraphXml(p);
    });

    // Standard A4 Section Properties (11906 x 16838 dxa with 1440 dxa = 1 inch margins)
    bodyContentXml += '<w:sectPr><w:pgSz w:w="11906" w:h="16838" w:orient="portrait"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440" w:header="720" w:footer="720" w:gutter="0"/><w:cols w:space="720"/><w:docGrid w:linePitch="360"/></w:sectPr>';

    const documentXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <w:body>
    ${bodyContentXml}
  </w:body>
</w:document>`;

    const contentTypesXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
  <Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>
  <Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>
  <Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/>
</Types>`;

    const relsXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
  <Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/>
  <Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/>
</Relationships>`;

    const wordRelsXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
</Relationships>`;

    const stylesXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:docDefaults>
    <w:rPrDefault>
      <w:rPr>
        <w:rFonts w:ascii="Calibri" w:hAnsi="Calibri" w:cs="Calibri"/>
        <w:sz w:val="22"/>
        <w:szCs w:val="22"/>
        <w:color w:val="334155"/>
        <w:lang w:val="en-US"/>
      </w:rPr>
    </w:rPrDefault>
  </w:docDefaults>
</w:styles>`;

    const corePropsXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:dcmitype="http://purl.org/dc/dcmitype/">
  <dc:title>${docTitle}</dc:title>
  <dc:creator>${author}</dc:creator>
  <cp:lastModifiedBy>${author}</cp:lastModifiedBy>
  <dcterms:created xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:type="dcterms:W3CDTF">2026-09-01T00:00:00Z</dcterms:created>
  <dcterms:modified xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:type="dcterms:W3CDTF">2026-09-01T00:00:00Z</dcterms:modified>
</cp:coreProperties>`;

    const appPropsXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties">
  <Application>LocalDoc Zero-Upload Engine</Application>
  <DocSecurity>0</DocSecurity>
  <Lines>1</Lines>
  <Paragraphs>${paragraphs.length}</Paragraphs>
</Properties>`;

    const zip = new MiniZip();
    zip.addFile('[Content_Types].xml', contentTypesXml);
    zip.addFile('_rels/.rels', relsXml);
    zip.addFile('word/_rels/document.xml.rels', wordRelsXml);
    zip.addFile('word/document.xml', documentXml);
    zip.addFile('word/styles.xml', stylesXml);
    zip.addFile('docProps/core.xml', corePropsXml);
    zip.addFile('docProps/app.xml', appPropsXml);

    return zip.generateBlob('application/vnd.openxmlformats-officedocument.wordprocessingml.document');
  }
}

// Global attachment & fallback
DocxBuilder.escapeXml = function(str) {
  if (!str && str !== 0) return '';
  return String(str)
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
};

/**
 * MiniZip — In-Browser ZIP Archive Encoder
 * Produces standard uncompressed (STORE) ZIP files compatible with Microsoft Word & Excel.
 */
class MiniZip {
  constructor() {
    this.files = [];
  }

  addFile(filename, content) {
    let bytes;
    if (typeof content === 'string') {
      bytes = new TextEncoder().encode(content);
    } else if (content instanceof Uint8Array) {
      bytes = content;
    } else if (content instanceof ArrayBuffer) {
      bytes = new Uint8Array(content);
    } else {
      bytes = new Uint8Array(0);
    }
    this.files.push({ name: filename, data: bytes });
  }

  generateBlob(mimeType = 'application/zip') {
    const parts = [];
    const cdEntries = [];
    let offset = 0;

    for (const file of this.files) {
      const nameBytes = new TextEncoder().encode(file.name);
      const dataBytes = file.data;
      const crc = this.crc32(dataBytes);
      const size = dataBytes.length;

      // Local file header (30 bytes + name)
      const localHeader = new Uint8Array(30 + nameBytes.length);
      const v = new DataView(localHeader.buffer);
      v.setUint32(0, 0x04034b50, true);  // Local header signature
      v.setUint16(4, 20, true);          // Version needed: 2.0
      v.setUint16(6, 0, true);           // General purpose flags
      v.setUint16(8, 0, true);           // Compression: STORE (0)
      v.setUint16(10, 0, true);          // Mod time
      v.setUint16(12, 0, true);          // Mod date
      v.setUint32(14, crc, true);        // CRC-32
      v.setUint32(18, size, true);       // Compressed size
      v.setUint32(22, size, true);       // Uncompressed size
      v.setUint16(26, nameBytes.length, true); // Filename length
      v.setUint16(28, 0, true);          // Extra field length
      localHeader.set(nameBytes, 30);

      parts.push(localHeader);
      parts.push(dataBytes);

      // Central directory header (46 bytes + name)
      const cdHeader = new Uint8Array(46 + nameBytes.length);
      const cdv = new DataView(cdHeader.buffer);
      cdv.setUint32(0, 0x02014b50, true); // Central directory signature
      cdv.setUint16(4, 20, true);         // Version made by
      cdv.setUint16(6, 20, true);         // Version needed
      cdv.setUint16(8, 0, true);          // Flags
      cdv.setUint16(10, 0, true);         // Compression: STORE
      cdv.setUint16(12, 0, true);         // Mod time
      cdv.setUint16(14, 0, true);         // Mod date
      cdv.setUint32(16, crc, true);       // CRC-32
      cdv.setUint32(20, size, true);      // Compressed size
      cdv.setUint32(24, size, true);      // Uncompressed size
      cdv.setUint16(28, nameBytes.length, true); // Filename length
      cdv.setUint16(30, 0, true);         // Extra field length
      cdv.setUint16(32, 0, true);         // Comment length
      cdv.setUint16(34, 0, true);         // Disk start
      cdv.setUint16(36, 0, true);         // Internal attributes
      cdv.setUint32(38, 0, true);         // External attributes
      cdv.setUint32(42, offset, true);    // Local header offset
      cdHeader.set(nameBytes, 46);

      cdEntries.push(cdHeader);
      offset += localHeader.length + dataBytes.length;
    }

    const cdOffset = offset;
    let cdSize = 0;
    for (const cd of cdEntries) {
      parts.push(cd);
      cdSize += cd.length;
    }

    // End of central directory record (22 bytes)
    const eocd = new Uint8Array(22);
    const eocdv = new DataView(eocd.buffer);
    eocdv.setUint32(0, 0x06054b50, true); // EOCD signature
    eocdv.setUint16(4, 0, true);          // Disk number
    eocdv.setUint16(6, 0, true);          // Disk with CD
    eocdv.setUint16(8, this.files.length, true);  // Entries on disk
    eocdv.setUint16(10, this.files.length, true); // Total entries
    eocdv.setUint32(12, cdSize, true);    // CD size
    eocdv.setUint32(16, cdOffset, true);  // CD offset
    eocdv.setUint16(20, 0, true);         // Comment length

    parts.push(eocd);
    return new Blob(parts, { type: mimeType });
  }

  crc32(bytes) {
    let crc = -1;
    for (let i = 0; i < bytes.length; i++) {
      crc = (crc >>> 8) ^ MiniZip.CRC_TABLE[(crc ^ bytes[i]) & 0xff];
    }
    return (crc ^ (-1)) >>> 0;
  }
}

MiniZip.CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let k = 0; k < 8; k++) {
      c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    }
    table[i] = c >>> 0;
  }
  return table;
})();

if (typeof window !== 'undefined') {
  window.DocxBuilder = DocxBuilder;
  window.MiniZip = MiniZip;
}
